import { procedure, router } from "../trpc";
import { authUser } from "../auth";
import { z } from "zod";
import db from "../database/db";
import { AutoTaskId, isAutoTask, Task, zTask } from "../../shared/Task";
import {
  taskAttributes,
  taskInclude,
} from "../database/models/attributesAndIncludes";
import {
  generalBadRequestError,
  noPermissionError,
  notFoundError,
} from "../errors";
import sequelize from "../database/sequelize";
import { zDateColumn } from "../../shared/DateColumn";
import moment from "moment";
import { Op, Transaction } from "sequelize";
import { isExamAboutToExpire } from "../../shared/exams";
import { scheduleNotification } from "./scheduledNotifications";
import { whereMentorshipIsOngoing } from "./mentorships";
import { isPermittedtoAccessMentee } from "./users";
import { isPermitted } from "../../shared/Role";
import User from "../../shared/User";

export async function listImpl(
  me: User,
  assigneeIds: string[],
  includeTasksCreatedByMe: boolean,
  includeDoneTasks: boolean,
  transaction?: Transaction,
): Promise<Task[]> {
  for (const assigneeId of assigneeIds) {
    if (
      assigneeId !== me.id &&
      // For mentors, only mentorship managers can see their tasks.
      !isPermitted(me.roles, "MentorshipAdmin") &&
      // For mentees, only mentorship managers and mentors can see their
      // tasks.
      !(await isPermittedtoAccessMentee(me, assigneeId, transaction))
    ) {
      throw noPermissionError("待办事项");
    }
  }

  return (
    await db.Task.findAll({
      where: {
        [Op.or]: [
          ...assigneeIds.map((assigneeId) => ({ assigneeId })),
          ...(includeTasksCreatedByMe ? [{ creatorId: me.id }] : []),
        ],
        ...(!includeDoneTasks && { done: false }),
      },
      attributes: taskAttributes,
      include: taskInclude,
      transaction,
    })
  ).map((n) => castTask(n));
}

const list = procedure
  .use(authUser())
  .input(
    z.object({
      assigneeIds: z.array(z.string()),
      includeTasksCreatedByMe: z.boolean(),
      includeDoneTasks: z.boolean(),
    }),
  )
  .output(z.array(zTask))
  .query(
    async ({
      ctx: { me },
      input: { assigneeIds, includeTasksCreatedByMe, includeDoneTasks },
    }) => {
      return await sequelize.transaction(async (transaction) => {
        return await listImpl(
          me,
          assigneeIds,
          includeTasksCreatedByMe,
          includeDoneTasks,
          transaction,
        );
      });
    },
  );

/**
 * We need this pseudo function because id and updatedAt are defined as an
 * optional field in the model but required by the zod type.
 */
export function castTask(n: any): Task {
  return zTask.parse(n);
}

export async function createImpl(
  me: User,
  assigneeId: string,
  markdown: string,
  transaction: Transaction,
): Promise<void> {
  if (markdown.trim().length === 0) {
    throw generalBadRequestError("待办事项不能为空。");
  }

  await db.Task.create(
    {
      creatorId: me.id,
      assigneeId,
      markdown: markdown.trim(),
      done: false,
    },
    { transaction },
  );

  await scheduleNotification("Task", assigneeId, transaction);
}

const create = procedure
  .use(authUser())
  .input(
    z.object({
      assigneeId: z.string(),
      markdown: z.string(),
    }),
  )
  .mutation(async ({ ctx: { me }, input: { assigneeId, markdown } }) => {
    await sequelize.transaction(async (transaction) => {
      await createImpl(me, assigneeId, markdown, transaction);
    });
  });

export async function updateImpl(
  me: User,
  id: number,
  assigneeId: string,
  markdown: string,
  transaction: Transaction,
): Promise<void> {
  if (markdown.trim().length === 0) {
    throw generalBadRequestError("待办事项不能为空。");
  }

  const task = await db.Task.findByPk(id, {
    attributes: taskAttributes,
    include: taskInclude,
    transaction,
  });
  checkForUpdate(castTask(task), me);

  await db.Task.update(
    {
      assigneeId,
      markdown: markdown.trim(),
    },
    {
      where: { id },
      transaction,
    },
  );

  await scheduleNotification("Task", assigneeId, transaction);
}

const update = procedure
  .use(authUser())
  .input(
    z.object({
      id: z.number(),
      assigneeId: z.string(),
      markdown: z.string(),
    }),
  )
  .mutation(async ({ ctx: { me }, input: { id, assigneeId, markdown } }) => {
    await sequelize.transaction(async (transaction) => {
      await updateImpl(me, id, assigneeId, markdown, transaction);
    });
  });

export async function updateDoneImpl(
  me: User,
  id: number,
  done: boolean,
  transaction: Transaction,
): Promise<void> {
  const task = await db.Task.findByPk(id, {
    attributes: taskAttributes,
    include: taskInclude,
    transaction,
  });
  checkForUpdate(castTask(task), me);
  await db.Task.update(
    { done },
    {
      where: { id },
      transaction,
    },
  );
}

const updateDone = procedure
  .use(authUser())
  .input(
    z.object({
      id: z.number(),
      done: z.boolean(),
    }),
  )
  .mutation(async ({ ctx: { me }, input: { id, done } }) => {
    await sequelize.transaction(async (transaction) => {
      await updateDoneImpl(me, id, done, transaction);
    });
  });

function checkForUpdate(task: Task | null, me: User) {
  if (!task) throw notFoundError("待办事项");

  if (
    isAutoTask(task) ||
    (task.assignee.id !== me.id && task.creator?.id !== me.id)
  ) {
    throw noPermissionError("待办事项", task.assignee.id);
  }
}

export async function getLastTasksUpdatedAtImpl(
  me: User,
  transaction?: Transaction,
): Promise<Date> {
  const ret = await db.Task.max("updatedAt", {
    where: {
      assigneeId: me.id,
      creatorId: isAutoTaskOrCreatorIsOther(me.id),
      done: false,
    },
    transaction,
  });
  return (ret as Date | null) ?? moment(0).toDate();
}

/**
 * @return excludes tasks that are done or created by the current user.
 */
const getLastTasksUpdatedAt = procedure
  .use(authUser())
  .output(zDateColumn)
  .query(async ({ ctx: { me } }) => {
    return await sequelize.transaction(async (transaction) => {
      return await getLastTasksUpdatedAtImpl(me, transaction);
    });
  });

export function isAutoTaskOrCreatorIsOther(assigneeId: string) {
  return { [Op.or]: [{ [Op.eq]: null }, { [Op.ne]: assigneeId }] };
}

export default router({
  list,
  create,
  update,
  updateDone,
  getLastTasksUpdatedAt,
});

export async function createAutoTasks(transaction: Transaction) {
  // Find all ongoing mentorships
  const mentorships = await db.Mentorship.findAll({
    where: whereMentorshipIsOngoing,
    attributes: [],
    include: [
      {
        association: "mentor",
        attributes: ["id", "state"],
      },
    ],
    transaction,
  });

  // Create study-comms tasks
  for (const m of mentorships) {
    if (isExamAboutToExpire(m.mentor.state?.commsExam)) {
      await createAutoTask(m.mentor.id, "study-comms", transaction);
    }
  }

  // Create study-handbook tasks
  for (const m of mentorships) {
    if (isExamAboutToExpire(m.mentor.state?.handbookExam)) {
      await createAutoTask(m.mentor.id, "study-handbook", transaction);
    }
  }
}

export async function createAutoTask(
  assigneeId: string,
  autoTaskId: AutoTaskId,
  transaction: Transaction,
) {
  const task = await db.Task.findOne({
    where: { assigneeId, autoTaskId },
    attributes: ["id", "done"],
    transaction,
  });

  // Do nothing if the task is already created and pending.
  if (task && !task.done) {
    console.log(`AutoTask ${autoTaskId} for ${assigneeId} is already created`);
    return;
  }

  console.log(`creating AutoTask ${autoTaskId} for user ${assigneeId}`);

  // Sequelize's upsert() doesn't work because it can't deal with the id column.
  if (task) {
    await task.update({ done: false }, { transaction });
  } else {
    await db.Task.create(
      {
        assigneeId,
        autoTaskId,
        done: false,
      },
      { transaction },
    );
  }

  await scheduleNotification("Task", assigneeId, transaction);
}

import { initTRPC } from "@trpc/server";
import { Context } from "pages/api/v1/[trpc]";

const trpc = initTRPC.context<Context>().create();

// Base router and procedure helpers
export const router = trpc.router;
export const procedure = trpc.procedure;
export const middleware = trpc.middleware;

import { ip } from "./ip";
import { middleware } from "./trpc";
import { TRPCError } from "@trpc/server";
import Role, { isPermitted } from "../shared/Role";
import { getServerSession } from "next-auth/next";
import { authOptions } from "../pages/api/auth/[...nextauth]";
import crypto from "crypto";
import { internalServerError } from "./errors";

/**
 * Authenticate for APIs used by applications as opposed to end users. Usage:
 *
 * $ curl -H "Authorization: Bearer ${INTEGRATION_AUTH_TOKEN}" \
 *  "${BASE_URL}/api/v1/foo.bar"
 */
export const authIntegration = () =>
  middleware(async ({ ctx, next }) => {
    const token: string | undefined =
      ctx.req.headers["authorization"]?.split(" ")[1];

    if (!token) throw unauthorizedError();

    const expected = process.env.INTEGRATION_AUTH_TOKEN;
    if (!expected) {
      throw internalServerError("INTEGRATION_AUTH_TOKEN is not set.");
    }

    if (
      token.length !== expected.length ||
      // Use timingSafeEqual to prevent timing attacks.
      !crypto.timingSafeEqual(Buffer.from(token), Buffer.from(expected))
    ) {
      throw invalidTokenError();
    }

    return await next({ ctx: {} });
  });

/**
 * Authenticate for APIs used by end users as opposed to integration
 * applications.
 */
export const authUser = (permitted?: Role | Role[]) =>
  middleware(async ({ ctx, next }) => {
    const session = await getServerSession(
      ctx.req,
      ctx.res,
      authOptions(ctx.req),
    );
    if (!session) throw unauthorizedError();

    if (!isPermitted(session.me.roles, permitted)) throw forbiddenError();

    return await next({
      ctx: {
        me: session.me,
        session,
      },
    });
  });

/**
 * Authenticate for webhooks.
 */
export const authWebhook = middleware(async ({ next }) => {
  if (!process.env.WEBHOOK_TOKEN) {
    throw internalServerError("WEBHOOK_TOKEN is required but not set.");
  }
  return await next();
});

const unauthorizedError = () =>
  new TRPCError({
    code: "UNAUTHORIZED",
    message: "请重新登录。",
  });

const invalidTokenError = () =>
  new TRPCError({
    code: "BAD_REQUEST",
    message: "验证令牌无效。",
  });

const forbiddenError = () =>
  new TRPCError({
    code: "FORBIDDEN",
    message: "禁止访问。",
  });

export { ip };

import { middleware } from "./trpc";
import proxyaddr from "proxy-addr";

/**
 * Attach client IP address to the context. Cannot be used in combination with
 * auth*().
 */
export const ip = () =>
  middleware(async ({ ctx, next }) => {
    // Determine the trusted proxies from the environment, defaulting to local
    // loopback and local networks
    const trustedProxies = process.env.TRUSTED_PROXIES
      ? process.env.TRUSTED_PROXIES.split(",").map((s) => s.trim())
      : ["loopback", "linklocal", "uniquelocal"];
    let clientIp: string | undefined;

    try {
      // Use proxy-addr to securely parse X-Forwarded-For by validating against
      // trusted proxies. NOTE: proxy-addr works with standard node
      // IncomingMessage request objects.
      clientIp = proxyaddr(ctx.req, trustedProxies);
    } catch {
      // Fallback in case of parse error
      clientIp = ctx.req.connection.remoteAddress;
    }

    console.log(
      `ip() middleware resolved client IP: ${clientIp} | X-Forwarded-For: ${ctx.req.headers["x-forwarded-for"]} | remoteAddress: ${ctx.req.connection?.remoteAddress}`,
    );

    return await next({
      ctx: {
        ...ctx,
        ip: clientIp,
      },
    });
  });

import z from "zod";

export const allRoles = [
  "SystemAlertSubscriber",

  "UserAdmin",
  "GroupAdmin",
  "OrgAdmin",

  "ProjectAdmin",

  "MentorshipAssessor",
  "MentorshipAdmin",
  "MentorshipOperator",

  // See `docs/Glossary.md` for the definitions of this type.
  "TransactionalMentor",
  // Mentor role is either a transactional or relational mentor.
  "Mentor",
  "Mentee",
  "Interviewer",
  "Volunteer",

  // Deprecated. Only to display legacy senior mentors on the
  // /mentors/manage page.
  "SeniorMentor",
] as const;

type Role = (typeof allRoles)[number];

export default Role;

export const zRoles = z.array(z.enum(allRoles));

/**
 * Use `rp()` to access this object for type safety.
 */
const RoleProfiles: {
  [key: string]: {
    // Why not simply use displayName as the role key? We're too lazy to type
    // Chinese characters everywhere.
    displayName: string;

    actions: string;

    // If the role can be automatically added to or removed from users.
    automatic?: boolean;

    // If the role can access user data without explicit relations with the user
    // (e.g. mentor-mentee relation)
    privilegedUserDataAccess?: boolean;
  };
} = {
  SystemAlertSubscriber: {
    displayName: "系统报警监听员",
    actions: "接受并处理系统异常事件的报警",
  },
  UserAdmin: {
    displayName: "用户管理员",
    actions: "管理用户基本信息",
    privilegedUserDataAccess: true,
  },
  GroupAdmin: {
    displayName: "会议管理员",
    actions: "管理会议分组和会议纪要",
    privilegedUserDataAccess: true,
  },
  OrgAdmin: {
    displayName: "机构管理员",
    actions: "管理机构信息、成员和所有者",
  },
  ProjectAdmin: {
    displayName: "项目管理员",
    actions: "管理项目信息",
  },

  MentorshipAssessor: {
    displayName: "一对一导师评估员",
    actions: "跟踪评估一对一导师辅导效果",
    privilegedUserDataAccess: true,
  },
  MentorshipAdmin: {
    displayName: "运营主管",
    actions: "管理学生信息、导师信息、面试信息、一对一学生导师匹配信息等",
    privilegedUserDataAccess: true,
  },
  MentorshipOperator: {
    displayName: "运营专员",
    actions: "负责导师和学生活动的运营",
    privilegedUserDataAccess: true,
  },

  Mentor: {
    displayName: "导师",
    actions: "辅助学子成长",
    automatic: true,
  },
  SeniorMentor: {
    displayName: "资深导师",
    actions: "辅助学子成长，指导其他导师",
  },
  TransactionalMentor: {
    displayName: "仅不定期导师",
    actions: "仅做不定期服务，不参与学生匹配",
  },
  Mentee: {
    displayName: "学生",
    actions: "接受导师辅助",
    automatic: true,
  },
  Interviewer: {
    displayName: "面试官",
    actions: "面试导师或学生候选人",
    automatic: true,
  },
  Volunteer: {
    displayName: "志愿者",
    actions: "可以浏览其他志愿者信息",
  },
};

export function roleProfile(role: Role) {
  return RoleProfiles[role];
}

export function displayName(role: Role) {
  return RoleProfiles[role].displayName;
}

/**
 * @param permitted When absent, this function always returns true.
 */
export function isPermitted(userRoles: Role[], permitted?: Role | Role[]) {
  if (permitted === undefined) return true;
  if (typeof permitted === "string") return userRoles.includes(permitted);
  return userRoles.some((r) => permitted.includes(r));
}

/**
 * TODO update codebase to use this function instead of manually removing roles
 */
export function removeRole(roles: Role[], role: Role) {
  return roles.filter((r) => r !== role);
}

/**
 * TODO update codebase to use this function instead of manually adding roles
 */
export function addRole(roles: Role[], role: Role) {
  return roles.includes(role) ? roles : [...roles, role];
}

import NextAuth, { NextAuthOptions } from "next-auth";
import db from "../../../api/database/db";
import {
  userAttributes,
  userInclude,
} from "../../../api/database/models/attributesAndIncludes";
import invariant from "../../../shared/invariant";
import User from "../../../api/database/models/User";
import { LRUCache } from "lru-cache";
import { isPermitted } from "../../../shared/Role";
import { noPermissionError } from "../../../api/errors";
import { NextApiRequest, NextApiResponse } from "next";
import { adapter } from "../../../api/auth/adapter";
import providers from "../../../api/auth/providers";
import { isSafeCallbackUrl } from "../../../shared/callbackUrl";

declare module "next-auth" {
  interface Session {
    me: User;
    impersonated: true | undefined;
    // The logout URL for the identity provider if the user signed in via SSO.
    federatedLogoutUrl?: string;
  }
}

export type ImpersonationRequest = {
  // The ID of the user to impersonate, or `null` to stop impersonation.
  impersonate: string | null;
};

const impersonateTokenKey = "imp";

export { adapter };

export function authOptions(req?: NextApiRequest): NextAuthOptions {
  return {
    // @ts-expect-error
    adapter,

    session: {
      strategy: "jwt",
    },

    providers,

    pages: {
      signIn: "/auth/login",
      // The login page respects the `?error=` URL param.
      error: "/auth/login",
    },

    // https://next-auth.js.org/configuration/callbacks
    callbacks: {
      redirect({ url, baseUrl }) {
        // Prevent Open Redirect vulnerabilities via protocol-relative URLs
        if (isSafeCallbackUrl(url)) {
          return new URL(url, baseUrl).toString();
        }
        try {
          const urlOrigin = new URL(url).origin;
          if (urlOrigin === baseUrl) return url;
          if (
            process.env.AUTH_YUANTU_SSO_ISSUER &&
            urlOrigin === new URL(process.env.AUTH_YUANTU_SSO_ISSUER).origin
          ) {
            return url;
          }
        } catch {
          // Invalid URL, fall through to default.
        }
        return baseUrl;
      },

      signIn: ({ account }) => {
        // https://github.com/nextauthjs/next-auth/discussions/469
        if (account?.provider === "embedded-wechat-qr") {
          // https://next-auth.js.org/configuration/options#cookies
          const csrf =
            req?.cookies?.["__Host-next-auth.csrf-token"]?.split("|")[0];
          const state = req?.query?.state;
          if (csrf === state) {
            return true;
          } else {
            console.error(
              "WeChat QR OAuth state is illegal, csrf:",
              csrf,
              "state:",
              state,
            );
            return false;
          }
        } else {
          return true;
        }
      },

      async jwt({ token, trigger, session, account }) {
        // The 'account' object is only present on the very first sign in.
        // We persist the provider in the token so we can check it in subsequent requests.
        if (account) {
          token.provider = account.provider;
        }

        // Handle session updates.
        // https://next-auth.js.org/getting-started/client#updating-the-session
        if (trigger == "update" && session) {
          const impersonate = (session as ImpersonationRequest).impersonate;
          if (impersonate === undefined) {
            return token;
          }
          if (impersonate === null) {
            delete token[impersonateTokenKey];
          } else {
            // https://www.ietf.org/id/draft-knauer-secure-webhook-token-00.html#name-jwt-structure
            const original = await db.User.findByPk(token.sub, {
              attributes: ["roles", "mergedTo"],
            });
            invariant(original, "original not found");

            const me = !original.mergedTo
              ? original
              : await db.User.findByPk(original.mergedTo, {
                  attributes: ["roles"],
                });
            invariant(me, "me not found");

            if (!isPermitted(me.roles, "UserAdmin")) {
              throw noPermissionError("用户", impersonate);
            }
            token[impersonateTokenKey] = impersonate;
          }
        }

        return token;
      },

      async session({ token, session }) {
        const impersonate = token[impersonateTokenKey] as string | undefined;
        const id = impersonate ?? token.sub;
        invariant(id, "id not found");

        const original = await userCache.fetch(id);
        invariant(original, "original not found");

        const actual = !original.mergedTo
          ? original
          : await userCache.fetch(original.mergedTo);
        invariant(actual, "actual not found");

        session.me = actual;
        if (impersonate) session.impersonated = true;
        // If the user signed in with yuantu-sso, expose the IdP's logout endpoint
        // so the frontend can redirect the user there upon logging out.
        if (
          token.provider === "yuantu-sso" &&
          process.env.AUTH_YUANTU_SSO_ISSUER &&
          process.env.AUTH_YUANTU_SSO_CLIENT_ID
        ) {
          const issuer = process.env.AUTH_YUANTU_SSO_ISSUER.replace(/\/+$/, "");
          session.federatedLogoutUrl = `${issuer}/api/oauth2/logout?client_id=${process.env.AUTH_YUANTU_SSO_CLIENT_ID}`;
        }

        return session;
      },
    },
  };
}

// https://next-auth.js.org/configuration/initialization#advanced-initialization
export default async function auth(req: NextApiRequest, res: NextApiResponse) {
  return await NextAuth(req, res, authOptions(req));
}

const userCache = new LRUCache<string, User>({
  max: 1000,
  // The TTL should not too short so most consecutive requests from a page load
  // should get a hit. It should not be too long to keep staleness in reasonable
  // control.
  ttl: 5 * 1000, // 5 sec
  // Do not update age so that no matter how eagerly users refreshes the page
  // the data is guaranteed to be fresh after TTL passes.
  // updateAgeOnGet: true,

  fetchMethod: async (id: string) => {
    const user = await db.User.findByPk(id, {
      attributes: [...userAttributes, "mergedTo"],
      include: userInclude,
    });
    // next-auth must have already created the user.
    invariant(user, `user not found: ${id}`);
    return user;
  },
});

/**
 * Call this method at all the places where fields in `userAttributes` are
 * updated.
 */
export function invalidateUserCache(userId: string) {
  userCache.delete(userId);
}

/**
