  partnershipId: z.string().uuid().nullable(),
  interviewId: z.string().uuid().nullable(),
});
export type Group = z.TypeOf<typeof zGroup>;

export function isOwned(g: Group) {
  return g.partnershipId || g.interviewId;
}

export function isPermittedToAccessGroup(u: User, g: Group): boolean {
  // Public groups allow everyone to see member list and join group meetings but
  // not to read group history including transcripts and summaries.
  return g.public || isPermittedToAccessGroupHistory(u, g);
}

export function isPermittedToAccessGroupHistory(u: User, g: Group): boolean {
  return (
    isPermitted(u.roles, "GroupAdmin") || g.users.some((gu) => gu.id === u.id)
  );
}

import { DateColumn } from "../DateColumn";
import { getTimestamp } from "./getTimestamp";

/**
 * Return -1 if d1 is earlier than d2. Treat undefined & null as earliest date.
 *
 * We avoid importing `moment` here to prevent bundling the entire ~280 KB
 * moment library into client bundles for simple date comparisons.
 */
export function compareDate(
  d1: Date | DateColumn | undefined | null,
  d2: Date | DateColumn | undefined | null,
) {
  if (d1 == d2) return 0;
  if (!d1) return -1;
  if (!d2) return 1;
  const t1 = getTimestamp(d1);
  const t2 = getTimestamp(d2);
  if (t1 === t2) return 0;
  return t2 > t1 ? -1 : 1;
}

import { DateColumn } from "../DateColumn";

export function getTimestamp(val: Date | DateColumn | unknown): number {
  if (val instanceof Date) return val.getTime();
  if (typeof val === "string" || typeof val === "number") {
    return new Date(val).getTime();
  }
  if (
    val &&
    typeof (val as { valueOf?: () => number }).valueOf === "function"
  ) {
    return Number((val as { valueOf: () => number }).valueOf());
  }
  return 0;
}

export function toChineseDayOfWeek(n: number): string {
  return ["一", "二", "三", "四", "五", "六", "日"][n - 1];
}

