/**
 * See docs/WeChat.md for details.
 */
import type { OAuthConfig, OAuthUserConfig } from "next-auth/providers/oauth";
import { unionId2Email } from "./fakeEmail";

/**
 * See docs/WeChat.md for unionid vs openid
 */
interface WeChatProfile {
  openid: string;
  nickname: string;
  sex: number;
  province: string;
  city: string;
  country: string;
  headimgurl: string;
  privilege: string[];
  unionid: string;
  [claim: string]: unknown;
}

export default function WeChatProvider(
  options: OAuthUserConfig<WeChatProfile> & {
    platformType: "OfficialAccount" | "WebsiteApp";
  },
): OAuthConfig<WeChatProfile> {
  const { clientId, clientSecret, platformType } = options;

  return {
    id: "wechat",
    name: "WeChat",
    type: "oauth",
    // style: { logo: "/img/wechat.svg", bg: "#fff", text: "#000" },
    checks: ["state"],

    // We need this option to allow next-auth to link 微信开放平台 & 微信公众平台
    // accounts that share the same UnionID. See docs/WeChat.md.
    allowDangerousEmailAccountLinking: true,

    authorization: {
      url:
        platformType === "OfficialAccount"
          ? "https://open.weixin.qq.com/connect/oauth2/authorize"
          : "https://open.weixin.qq.com/connect/qrconnect",
      params: {
        appid: clientId,
        scope:
          platformType === "OfficialAccount"
            ? "snsapi_userinfo"
            : "snsapi_login",
      },
    },

    token: {
      async request({ params }) {
        try {
          if (!params.code) throw new Error("No code provided");
          const url = new URL(
            "https://api.weixin.qq.com/sns/oauth2/access_token",
          );
          url.searchParams.set("appid", clientId);
          url.searchParams.set("secret", clientSecret);
          url.searchParams.set("code", params.code);
          url.searchParams.set("grant_type", "authorization_code");
          const response = await fetch(url);
          const data = await response.json();
          return { tokens: data };
        } catch (error) {
          console.error("WeChat token request failed:", error);
          throw new Error("微信登录失败,请重试");
        }
      },
    },

    userinfo: {
      async request({ tokens }) {
        if (!tokens.access_token) {
          throw new Error("未获取到微信授权");
        }
        const url = new URL("https://api.weixin.qq.com/sns/userinfo");
        url.searchParams.set("access_token", tokens.access_token!);
        url.searchParams.set("openid", String(tokens.openid));
        url.searchParams.set("lang", "zh_CN");
        const response = await fetch(url);
        return response.json();
      },
    },

    profile(profile) {
      return {
        // next-auth saves it to the `provider_account_id` column of the
        // `accounts` table.
        id: profile.unionid,

        // next-auth rely on email to search for existing users. We don't store
        // the email in the database. See code in adapter.ts.
        email: unionId2Email(profile.unionid),
      };
    },

    options,
  };
}

import type { OAuthConfig, OAuthUserConfig } from "next-auth/providers/oauth";
import { TokenSet } from "openid-client";
import { ssoUserId2Email } from "./fakeEmail";

export default function YuantuSsoProvider(
  options: OAuthUserConfig<any> & { issuer: string },
): OAuthConfig<any> {
  const { clientId, clientSecret, issuer } = options;

  return {
    id: "yuantu-sso",
    name: "YuanTu SSO",
    type: "oauth",
    // Our in-house OAuth2 provider signs id_token with HS256 (shared client
    // secret),
    // so we must override openid-client's RS256 default expectation.
    client: { id_token_signed_response_alg: "HS256" },
    clientId,
    clientSecret,
    issuer,
    // We need this option to allow next-auth to link  accounts that share the
    // same user id on the sso server.
    allowDangerousEmailAccountLinking: true,
    authorization: {
      url: `${issuer}/api/oauth2/authorize`,
      params: { scope: "openid profile email phone" },
    },
    token: { url: `${issuer}/api/oauth2/token` },
    userinfo: {
      url: `${issuer}/api/oauth2/userinfo`,
      // NextAuth otherwise uses only id_token claims for the profile when
      // `idToken` is enabled. Our id_token carries `sub` only; additional
      // fields such as name and phone number come from the OIDC userinfo
      // response (see `oauth2/userinfo.ts`).
      request({ client, tokens }) {
        return client.userinfo(
          tokens instanceof TokenSet ? tokens : new TokenSet(tokens),
        );
      },
    },
    checks: ["pkce", "state"],
    profile(profile) {
      // For more information on why we encode the ssoUserId into the email,
      // see WeChatProvider.profile() function.
      return {
        id: profile.sub,
        email: ssoUserId2Email(profile.sub),
        realEmail: profile.email ?? undefined,
        name: profile.name ?? undefined,
        phone: profile.phone_number ?? undefined,
      };
    },
    options,
  };
}

export const loginCallbackUrlKey = "callbackUrl";
export const profileCallbackUrlKey = "profileCallbackUrl";

/**
 * Checks if a URL is a safe local path for redirection.
 * A path is considered safe if it starts with a single '/' and is not followed
 * by another '/' or '\', which could be used for protocol-relative redirects.
 * It also implicitly prevents 'javascript:' URLs as they don't start with '/'.
 */
export function isSafeCallbackUrl(url: string | null | undefined): boolean {
  if (
    !url ||
    !url.startsWith("/") ||
    url.startsWith("//") ||
    url.startsWith("/\\")
  ) {
    return false;
  }
  return true;
}

/**
 * Returns a safe local path for redirection, falling back to '/' if invalid.
 */
export function sanitizeCallbackUrl(url: string | null | undefined): string {
  return isSafeCallbackUrl(url) ? url! : "/";
}

import { z } from "zod";
import { zMinUser } from "./User";
import { zDateColumn } from "./DateColumn";
import { prettifyDate } from "./strings/prettifyDate";
import { defaultExamExpiryDays } from "./exams";
import { UserState } from "./UserState";
import invariant from "./invariant";
import moment from "moment";

export const zAutoTaskId = z.enum(["study-comms", "study-handbook"]);
export type AutoTaskId = z.TypeOf<typeof zAutoTaskId>;

/**
 * There are two types of tasks:
 * - Auto tasks: created by the system and assigned to a user.
 * - Manual tasks: created by a user and assigned to either another user or
 *   the same user.
 *
 * The task is an auto task if and only if the creator is null.
 */
export const zTask = z.object({
  id: z.number(),

  assignee: zMinUser,
  creator: zMinUser.nullable(),

  // This field is used only when creator is null.
  autoTaskId: zAutoTaskId.nullable(),

  // This field is used only when creator is not null.
  markdown: z.string().nullable(),

  done: z.boolean(),

  updatedAt: zDateColumn,
});
export type Task = z.TypeOf<typeof zTask>;

/**
 * @param assigneeState undefined if the user state is not loaded in frontend
 */
export function getTaskMarkdown(
  t: Task,
  assigneeState: UserState | undefined,
  baseUrl: string,
): string {
  if (t.autoTaskId === null) {
    invariant(t.markdown !== null, "both autoTaskId and markdown are null");
    return t.markdown;
  } else if (
    t.autoTaskId === "study-comms" ||
    t.autoTaskId === "study-handbook"
  ) {
    const link =
      t.autoTaskId === "study-comms"
        ? `[《学生通讯原则》](${baseUrl}/study/comms)`
        : `[《社会导师手册》](${baseUrl}/study/handbook)`;
    const base = `${link}自学与评测`;
    const examPassedAt =
      t.autoTaskId === "study-comms"
        ? assigneeState?.commsExam
        : assigneeState?.handbookExam;

    if (t.done || !assigneeState) {
      return `请完成${base}。`;
    } else if (!examPassedAt) {
      // The user has never passed the exam.
      return `请完成${base}，之后即可访问相关的学生资料。`;
    } else {
      // The user has passed the exam but about to expire.
      const expiry = moment(examPassedAt).add(defaultExamExpiryDays, "days");
      const expired = expiry.isBefore(moment());
      return (
        `${base}需每年完成一次。你的上次评测结果**${expired ? "已" : "将"}于` +
        `${prettifyDate(expiry.toDate())}过期**。` +
        `为确保继续访问学生资料，请尽早完成评测。`
      );
    }
  } else {
    invariant(false, "invalid autoTaskId");
  }
}

export function isAutoTask(task: Task) {
  invariant(
    (task.creator !== null) === (task.autoTaskId === null),
    `creator and autoTaskId: ${task.creator} ${task.autoTaskId}`,
  );
  return task.creator === null;
}

import { DateColumn } from "../DateColumn";
import { diffInMinutes } from "./diffInMinutes";

export function prettifyDate(str: Date | DateColumn) {
  const date = new Date(str);
  const now = new Date();
  const dim = diffInMinutes(date, now);
  if (dim < -24 * 60) return `${Math.floor(-dim / 24 / 60)} 天后`;
  if (dim < -60) return `${Math.floor(-dim / 60)} 小时后`;
  if (dim < 0) return `${-dim} 分钟后`;
  if (dim < 1) return `刚刚`;
  if (dim < 60) return `${dim} 分钟前`;
  if (dim < 24 * 60) return `${Math.floor(dim / 60)} 小时前`;
  if (dim < 30 * 24 * 60) return `${Math.floor(dim / 24 / 60)} 天前`;
  if (date.getFullYear() == now.getFullYear()) {
    return date.toLocaleDateString("zh-cn", { day: "numeric", month: "short" });
  } else {
    return date.toLocaleDateString("zh-cn", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  }
}

import { DateColumn } from "../DateColumn";
import { getTimestamp } from "./getTimestamp";

export function diffInMinutes(from: Date | DateColumn, to: Date | DateColumn) {
  const fromMs = getTimestamp(from);
  const toMs = getTimestamp(to);
  return Math.round((toMs - fromMs) / 60000);
}

import { DateColumn } from "./DateColumn";
import moment from "moment";
import { Features } from "./Features";

export const defaultExamExpiryDays = 365;

// 300 days instead of 365 days because the start of the next interview
// cycle varies from year to year.
export const interviewExamExpiryDays = 300;

/**
 * @param lastPassed Assume the exam is expired if undefined
 */
export function isExamExpired(
  lastPassed: DateColumn | undefined,
  expiryDays: number = defaultExamExpiryDays,
) {
  if (!lastPassed) return true;
  return moment().diff(moment(lastPassed), "days") > expiryDays;
}

/**
 * @param lastPassed Assume the exam is expired if undefined
 * @returns Whether the exam is about to expire or already expired
 */
export function isExamAboutToExpire(
  lastPassed: DateColumn | undefined,
  expiryDays: number = defaultExamExpiryDays,
) {
  return isExamExpired(lastPassed, expiryDays - 30);
}

export function calculateExamsRequired({
  state,
  features,
}: {
  state?: {
    commsExam?: DateColumn;
    menteeInterviewerExam?: DateColumn;
    handbookExam?: DateColumn;
  };
  features: Features;
}) {
  if (state === undefined) {
    return {
      commsExamRequired: undefined,
      interviewExamRequired: undefined,
      handbookExamRequired: undefined,
    };
  }
  if (!features.exams) {
    return {
      commsExamRequired: false,
      interviewExamRequired: false,
      handbookExamRequired: false,
    };
  }

  return {
    commsExamRequired: isExamExpired(state.commsExam),
    interviewExamRequired: isExamExpired(
      state.menteeInterviewerExam,
      interviewExamExpiryDays,
    ),
    handbookExamRequired: isExamExpired(state.handbookExam),
  };
}

