export async function scheduleNotification(
  type: ScheduledNotificationType,
  subjectId: string,
  transaction: Transaction,
) {
  const count = await db.ScheduledNotification.count({
    where: { type, subjectId },
    transaction,
  });

  if (count > 0) {
    console.log(`${type} notification already scheduled for ${subjectId}`);
  } else {
    console.log(`scheduling ${type} notification for ${subjectId}`);
    await db.ScheduledNotification.create({ type, subjectId }, { transaction });
  }
}

const minDelayInMinutes = 5;

export async function sendScheduledNotifications(
  passedTransaction?: Transaction,
) {
  const doWork = async (transaction: Transaction) => {
    const all = await db.ScheduledNotification.findAll({
      attributes: ["id", "type", "subjectId", "createdAt"],
      transaction,
    });
    console.log(`Found ${all.length} scheduled notification`);

    for (const row of all) {
      const delayed = moment(row.createdAt).add(minDelayInMinutes, "minutes");
      if (delayed.isAfter(moment())) {
        console.log(`Delaying notification with row id ${row.id}`);
        continue;
      }

      // Offset by 1 second to counter any time skew at commit time.
      const timestamp = moment(row.createdAt).subtract(1, "second");

      switch (row.type) {
        case "Kudos":
          await notifyKudos(row.subjectId, timestamp, transaction);
          break;
        case "Chat":
          await notifyChats(row.subjectId, timestamp, transaction);
          break;
        case "Task":
          await notifyTasks(row.subjectId, timestamp, transaction);
          break;
        default:
          invariant(false, `Unknown scheduled notification type: ${row.type}`);
      }

      await db.ScheduledNotification.destroy({
        where: { id: row.id },
        transaction,
      });
    }
  };

  if (passedTransaction) {
    await doWork(passedTransaction);
  } else {
    await sequelize.transaction(doWork);
  }
}

async function notifyTasks(
  assigneeId: string,
  timestamp: Moment,
  transaction: Transaction,
) {
  const tasks = await db.Task.findAll({
    where: {
      assigneeId,
      creatorId: isAutoTaskOrCreatorIsOther(assigneeId),
      done: false,
      updatedAt: isOnOrAfter(timestamp),
    },
    attributes: taskAttributes,
    include: taskInclude,
    transaction,
  });

  const assignee = await db.User.findByPk(assigneeId, {
    attributes: ["name", "state"],
    transaction,
  });
  if (!assignee) throw Error(`Assignee not found: ${assigneeId}`);

  const name = formatUserName(assignee.name, "friendly");
  const htmls = await Promise.all(
    tasks.map((t) => {
      const md = getTaskMarkdown(
        castTask(t),
        assignee.state ?? {},
        getBaseUrl(),
      );
      return markdown2html(md);
    }),
  );

  if (htmls.length === 0) {
    console.log(
      `No tasks to send to assignee ${assigneeId}, assuming assignee ` +
        `has completed the tasks that triggered this scheduled notification.`,
    );
    return;
  }

  const templateData = {
    name,
    delta: `<ul><li>${htmls.join("</li><li>")}</li></ul>`,
  };

  await notify(
    "待办事项",
    [assigneeId],
    {
      email: "E_114706042504",
      domesticSms: "rw7iV2",
      internationalSms: "iodG74",
    },
    templateData,
    transaction,
  );

  notifyRolesIgnoreError(
    ["SystemAlertSubscriber"],
    "发送待办事项邮件",
    JSON.stringify(templateData),
  );
}

function isOnOrAfter(timestamp: Moment) {
  return { [Op.gte]: timestamp.toISOString() };
}

function formatUserlink(u: MinUser) {
  return (
    `<a href="${getBaseUrl()}${getUserUrl(u)}">` +
    formatUserName(u.name, "formal") +
    `</a>`
  );
}

async function notifyKudos(
  receiverId: string,
  timestamp: Moment,
  transaction: Transaction,
) {
  const receiver = await db.User.findByPk(receiverId, {
    attributes: ["name", "likes", "kudos"],
    transaction,
  });
  if (!receiver) throw Error(`User not found: ${receiverId}`);

  const delta = await db.Kudos.findAll({
    where: {
      receiverId,
      createdAt: isOnOrAfter(timestamp),
    },
    attributes: kudosAttributes,
    include: kudosInclude,
    transaction,
  });

  const giver2user: Record<string, MinUser> = {};
  const giver2likes: Record<string, number> = {};
  const giver2kudos: Record<string, string[]> = {};
  for (const k of delta) {
    giver2user[k.giver.id] = k.giver;
    if (k.text === null) {
      giver2likes[k.giver.id] = (giver2likes[k.giver.id] ?? 0) + 1;
    } else {
      giver2kudos[k.giver.id] = [...(giver2kudos[k.giver.id] ?? []), k.text];
    }
  }

  const message = [
    ...Object.entries(giver2likes).map(([giverId, likes]) => {
      const giver = giver2user[giverId];
      return `${formatUserlink(giver)}刚刚给你点了 ${likes} 个赞`;
    }),
    ...Object.entries(giver2kudos).map(([giverId, kudos]) => {
      const giver = giver2user[giverId];
      const kudosText = kudos.map((k) => `“${k}”`).join("，");
      return `${formatUserlink(giver)}刚刚夸了你：<b>${kudosText}</b>`;
    }),
  ].join("<br />");

  const receiverName = formatUserName(receiver.name, "friendly");
  const templateData = {
    name: receiverName,
    delta: message,
    total: String((receiver.likes ?? 0) + (receiver.kudos ?? 0)),
  };

  await notify(
    "点赞",
    [receiverId],
    {
      email: "E_114706274956",
      domesticSms: "lQbr42",
      internationalSms: "GYEm92",
    },
    templateData,
    transaction,
  );

  notifyRolesIgnoreError(
    ["SystemAlertSubscriber"],
    "发送点赞通知",
    JSON.stringify(templateData),
  );
}

async function notifyChats(
  roomId: string,
  timestamp: Moment,
  transaction: Transaction,
) {
  const room = await db.ChatRoom.findByPk(roomId, {
    attributes: ["id"],
    include: [
      {
        association: "mentee",
        attributes: minUserAttributes,
      },
    ],
    transaction,
  });
  if (!room) throw Error(`Chat room not found: ${roomId}`);

  invariant(room.mentee, "Only mentee rooms are supported for now");

  /**
   * Compute receipients which should include mentors of all ongoing relational
   * mentorships and MentorshipAdmins.
   */
  const userId2receipients: Record<string, User> = {};

  // Force type check
  const role: Role = "MentorshipAdmin";
  (
    await db.User.findAll({
      where: { roles: { [Op.contains]: [role] } },
      attributes: userAttributes,
      transaction,
    })
  ).forEach((u) => (userId2receipients[u.id] = u));

  (
    await db.Mentorship.findAll({
      where: {
        menteeId: room.mentee.id,
        transactional: false,
        [Op.or]: [{ endsAt: isOnOrAfter(moment()) }, { endsAt: null }],
      },
      attributes: [],
      include: [
        {
          association: "mentor",
          attributes: userAttributes,
        },
      ],
      transaction,
    })
  ).forEach((m) => {
    userId2receipients[m.mentor.id] = m.mentor;
  });

  const delta = await db.ChatMessage.findAll({
    where: {
      roomId,
      [Op.or]: [
        { createdAt: isOnOrAfter(timestamp) },
        { updatedAt: isOnOrAfter(timestamp) },
      ],
    },
    attributes: chatMessageAttributes,
    include: chatMessageInclude,
    transaction,
  });

  const menteeName = formatUserName(room.mentee.name, "formal");

  await Promise.all(
    Object.values(userId2receipients).map(async (u) => {
      // Skip messages authored by the receipient themselves.
      const filtered = delta.filter((m) => m.user.id !== u.id);
      if (filtered.length === 0) return;

      // Display the name of the author if there is only one author, otherwise
      // display "多人".
      const authors =
        filtered
          .map((m) => m.user.id)
          .filter((id, i, arr) => arr.indexOf(id) === i).length === 1
          ? formatUserName(filtered[0].user.name)
          : "多人";

      invariant(room.mentee, "Only mentee rooms are supported for now");

      await notify(
        "内部笔记",
        [u.id],
        {
          email: "E_114702895735",
          domesticSms: "mUMBp2",
          internationalSms: "G9qHA3",
        },
        {
          menteeName,
          authors,
          roomLink: `${getBaseUrl()}/mentees/${room.mentee.id}`,
          delta: filtered
            .map((m) => {
              const verb = moment(m.createdAt).isAfter(timestamp)
                ? "新增"
                : `更新了${prettifyDate(m.createdAt)}创建的`;
              const truncated =
                m.markdown.length > 200
                  ? m.markdown.slice(0, 200) + "..."
                  : m.markdown;
              return (
                `<b>${formatUserlink(m.user)}${verb}笔记: </b>` +
                `<br /><br />` +
                // This is a big quotation mark.
                `<span style="color: gray;">❝</span>` +
                `${truncated}”`
              );
            })
            .join("<br /><br />"),
        },
        transaction,
      );
    }),
  );
}

export default function getBaseUrl() {
  if (typeof window !== "undefined") return window.location.origin;
  if (process.env.NEXTAUTH_URL) return process.env.NEXTAUTH_URL;
  return `http://localhost:${process.env.PORT ?? 3000}`;
}

/**
 * We don't use static imports to avoid the following problem:
 * /Users/weihanwang/repos/app/node_modules/ts-node/dist/index.js:851
 *            return old(m, filename);
 *                  ^
 * Error [ERR_REQUIRE_ESM]: require() of ES Module ... from ... not supported.
 * Instead change the require of index.js in ... to a dynamic import() which is
 * available in all CommonJS modules.
 */
import { defaultSchema } from "rehype-sanitize";

/**
 * By default, rehype-sanitize strips tags but leaves
 * their text content behind. This could lead to CSS
 * injection if a <style> tag's text content is retained.
 * We explicitly instruct it to completely remove script
 * and style tags and their contents.
 */
export const sanitizeSchema = {
  ...defaultSchema,
  strip: ["script", "style"],
};

export default async function markdown2html(markdown: string) {
  const { unified } = await import("unified");
  const { default: remarkGfm } = await import("remark-gfm");
  const { default: remarkParse } = await import("remark-parse");
  const { default: remarkRehype } = await import("remark-rehype");
  const { default: rehypeSanitize } = await import("rehype-sanitize");
  const { default: rehypeStringify } = await import("rehype-stringify");
  const file = await unified()
    .use(remarkParse)
    .use(remarkGfm)
    .use(remarkRehype)
    .use(rehypeSanitize, sanitizeSchema)
    .use(rehypeStringify)
    .process(markdown);
  return file.toString();
}

import { Op, Transaction } from "sequelize";
import { NotificationType } from "shared/UserPreference";
import db from "./database/db";
import { sms } from "./sms";
import { email } from "./email";
import getBaseUrl from "shared/getBaseUrl";
import Role from "shared/Role";
import sequelize from "./database/sequelize";

type Templates = {
  // AokSend email template id.
  email: string;
  // Submail SMS template ids.
  domesticSms: string;
  internationalSms: string;
};

export function notifyRolesIgnoreError(
  roles: Role[],
  subject: string,
  content: string,
) {
  const logError = (e: any) => {
    console.log(
      `notifyRolesIgnoreError() ignored error: ${roles}, ${subject}, ${e}`,
    );
  };
  try {
    // Do not use the transaction from the caller so the caller can proceed
    // without waiting for us.
    void sequelize.transaction(async (transaction) => {
      try {
        await notifyRoles(roles, subject, content, transaction);
      } catch (e) {
        logError(e);
      }
    });
  } catch (e) {
    logError(e);
  }
}

export async function notifyRoles(
  roles: Role[],
  subject: string,
  content: string,
  transaction: Transaction,
) {
  const userIds: Set<string> = new Set();
  for (const role of roles) {
    const users = await db.User.findAll({
      where: { roles: { [Op.contains]: [role] } },
      attributes: ["id"],
      transaction,
    });
    users.forEach((u) => userIds.add(u.id));
  }
  await notify(
    "基础",
    Array.from(userIds),
    {
      email: "E_114706970517",
      domesticSms: "JCGmM2",
      internationalSms: "2VFsY",
    },
    {
      subject,
      content,
    },
    transaction,
  );
}

/**
 * `templateVariables` should include variables needed for all three templates.
 */
export async function notify(
  type: NotificationType,
  userIds: string[],
  templates: Templates,
  templateVariables: Record<string, string>,
  transaction: Transaction,
) {
  const users = await db.User.findAll({
    where: { id: { [Op.in]: userIds } },
    attributes: ["email", "phone", "preference"],
    transaction,
  });

  const smsUsers = users.filter(
    (u) =>
      u.phone &&
      !u.preference?.smsDisabled?.includes("基础") &&
      !u.preference?.smsDisabled?.includes(type),
  );
  const smsPromise = sms(
    templates.domesticSms,
    templates.internationalSms,
    smsUsers.map((u) => ({
      to: u.phone!,
      vars: templateVariables,
    })),
  );

  const emailUsers = users.filter(
    (u) =>
      u.email &&
      !u.preference?.emailDisabled?.includes("基础") &&
      !u.preference?.emailDisabled?.includes(type),
  );
  const emailPromise = email(
    emailUsers.map((u) => u.email!),
    templates.email,
    templateVariables,
    getBaseUrl(),
  );

  // Parallelize to speed up the function
  await Promise.all([smsPromise, emailPromise]);
}

/**
 * Low-level API for sending transactional SMS. Use higher level API notify*()
 * when possible.
 */
import z from "zod";
import axios, { AxiosResponse } from "axios";
import { internalServerError } from "./errors";
import { chinaPhonePrefix } from "../shared/strings/chinaPhonePrefix";

export const idTokenInternationalSmsTemplateId = "0Rr8G";

export async function sms(
  domesticTemplateId: string,
  internationalTemplateId: string,
  templateData: {
    to: string;
    vars: Record<string, string>;
  }[],
) {
  // Skip everything in unittest. https://stackoverflow.com/a/29183140
  if (typeof global.it === "function") return;

  console.log(
    `Sending SMS via Submail, template id:`,
    `["${domesticTemplateId}", "${internationalTemplateId}"],`,
    `data: ${JSON.stringify(templateData, null, 2)}`,
  );

  const domestic = templateData
    .filter((t) => t.to.startsWith(chinaPhonePrefix))
    .map((t) => ({
      to: t.to.slice(chinaPhonePrefix.length),
      vars: t.vars,
    }));
  if (domestic.length > 0) {
    const appid = process.env.SUBMAIL_DOMESTIC_APP_ID;
    const appKey = process.env.SUBMAIL_DOMESTIC_APP_KEY;
    if (!appKey || !appid) {
      console.log("Domestic Submail not configured. Skip actual API.");
      return;
    }

    const form = new FormData();
    form.append("appid", appid);
    form.append("signature", appKey);
    form.append("project", domesticTemplateId);
    form.append("multi", JSON.stringify(domestic));

    // https://www.mysubmail.com/documents/eM4rY2
    handleResponse(
      await axios.post("https://api-v4.mysubmail.com/sms/multixsend", form, {
        headers: { "Content-Type": "multipart/form-data" },
      }),
    );
  }

  const international = templateData.filter(
    (t) => !t.to.startsWith(chinaPhonePrefix),
  );
  if (international.length > 0) {
    const appid = process.env.SUBMAIL_INTERNATIONAL_APP_ID;
    const appKey = process.env.SUBMAIL_INTERNATIONAL_APP_KEY;
    if (!appKey || !appid) {
      console.log("International Submail not configured. Skip actual API.");
      return;
    }

    const form = new FormData();
    form.append("appid", appid);
    form.append("signature", appKey);
    form.append("project", internationalTemplateId);
    form.append("multi", JSON.stringify(international));

    // https://www.mysubmail.com/documents/B70hy
    const response = await axios.post(
      "https://api-v4.mysubmail.com/internationalsms/multixsend",
      form,
      { headers: { "Content-Type": "multipart/form-data" } },
    );

    /**
     * Ignore errors for international SMS that is not for phone verification.
     * This is because Submail.com doesn't guarantee the delivery of these SMS.
     * For each country, Submail.com may need the service provider to obtain
     * permits from that country's mobile operators first to send
     * non-verification SMS to that country.
     */
    handleResponse(
      response,
      internationalTemplateId !== idTokenInternationalSmsTemplateId,
    );
  }
}

function handleResponse(response: AxiosResponse, ignoreError: boolean = false) {
  if (response.status !== 200) {
    console.log(
      `部分短信发送失败（忽略错误=${ignoreError}）：`,
      response.status,
      response.data,
    );
    if (!ignoreError) throw internalServerError("短信发送失败。请联系客服。");
  }

  const zResult = z.object({
    status: z.string(),
    code: z.number().optional(),
    msg: z.string().optional(),
  });

  // Handle either a single result or an array of multiple results
  const result = z.union([zResult, z.array(zResult)]).parse(response.data);
  const results = Array.isArray(result) ? result : [result];

  if (results.some((r) => r.status !== "success")) {
    console.log(`部分短信发送失败（忽略错误=${ignoreError}）：`, results);
    if (!ignoreError) throw internalServerError("短信发送失败。请联系客服。");
  }
}

