const list = procedure
  .use(
    authUser([
      "UserAdmin",
      "GroupAdmin",
      "MentorshipAdmin",
      "MentorshipOperator",
    ]),
  )
  .input(zUserFilter)
  .output(
    z.object({
      items: z.array(zUserWithMergeInfo),
